//   MODE_PKFMA    — f16vec2 multiply-add, RDNA's packed-fp16 ALU (v_pk_fma_f16)
//   MODE_DOT4     — dotPacked4x8AccSatEXT, the packed int8 dot (v_dot4_i32_i8)
//   MODE_WMMA_F16 — coopMatMulAdd fp16->fp32, the matrix cores
//   MODE_WMMA_I8  — coopMatMulAdd int8->int32, the matrix cores

#if defined(MODE_PKFMA)
#extension GL_EXT_shader_16bit_storage : enable
#extension GL_EXT_shader_explicit_arithmetic_types_float16 : enable
#endif

#if defined(MODE_DOT4)
#extension GL_EXT_integer_dot_product : enable
#endif

#if defined(MODE_WMMA_F16) || defined(MODE_WMMA_I8)
#extension GL_KHR_cooperative_matrix : enable
#extension GL_KHR_memory_scope_semantics : enable
#endif

#if defined(MODE_WMMA_F16)
#extension GL_EXT_shader_16bit_storage : enable
#extension GL_EXT_shader_explicit_arithmetic_types_float16 : enable
#endif

#if defined(MODE_WMMA_I8)
#extension GL_EXT_shader_8bit_storage : enable
#extension GL_EXT_shader_explicit_arithmetic_types_int8 : enable
#extension GL_EXT_shader_explicit_arithmetic_types_int32 : enable
#endif

// Number of independent accumulator chains. More hides more latency at the
// cost of registers; swept from the host side via separate -DACC variants.
#ifndef ACC
#define ACC 8
#endif

// One workgroup == one subgroup (64 lanes on this device), matching the
// coopmat kernels: the cooperative-matrix scope is gl_ScopeSubgroup, so a
// workgroup-per-subgroup keeps "waves in flight" equal to the dispatched
// workgroup count.
// WAVE (KERNELS.md G0): the workgroup is one subgroup of this many lanes; the
// host pins the size with VK_EXT_subgroup_size_control when it is 32. The
// scalar modes index lanes at lid+64 and are only built at 64; the WMMA modes
// are what wave32 is measured on, because the transposed attention runs there.
#ifndef WAVE
#define WAVE 64
#endif
layout(local_size_x = WAVE) in;

#if defined(MODE_WMMA_F16) || defined(MODE_WMMA_I8)
// Bound at pipeline creation to a shape the device actually reports (see
// vk.PhysicalDevice.CooperativeMatrixShapes), same as the GEMM coopmat kernels.
layout(constant_id = 0) const uint TILE_M = 16;
layout(constant_id = 1) const uint TILE_N = 16;
layout(constant_id = 2) const uint TILE_K = 16;
#endif

#if defined(MODE_PKFMA) || defined(MODE_WMMA_F16)
layout(binding = 0) readonly buffer In { float16_t src[]; };
#elif defined(MODE_DOT4)
layout(binding = 0) readonly buffer In { uint src[]; };
#elif defined(MODE_WMMA_I8)
layout(binding = 0) readonly buffer In { int8_t src[]; };
#else
layout(binding = 0) readonly buffer In { float src[]; };
#endif

#if defined(MODE_DOT4)
layout(binding = 1) writeonly buffer Out { int dst[]; };
#elif defined(MODE_WMMA_I8)
layout(binding = 1) writeonly buffer Out { int32_t dst[]; };
#else
layout(binding = 1) writeonly buffer Out { float dst[]; };
#endif

layout(push_constant) uniform PC {
    uint reps; // multiply-add issues per accumulator chain
} pc;

void main() {
    uint lid = gl_LocalInvocationID.x;
    uint gid = gl_GlobalInvocationID.x;

#if defined(MODE_WMMA_F16)
    coopmat<float16_t, gl_ScopeSubgroup, TILE_M, TILE_K, gl_MatrixUseA> matA;
    coopmat<float16_t, gl_ScopeSubgroup, TILE_K, TILE_N, gl_MatrixUseB> matB;
    coopMatLoad(matA, src, 0, TILE_K, gl_CooperativeMatrixLayoutRowMajor);
    coopMatLoad(matB, src, 0, TILE_N, gl_CooperativeMatrixLayoutRowMajor);

    coopmat<float, gl_ScopeSubgroup, TILE_M, TILE_N, gl_MatrixUseAccumulator> acc[ACC];
    for (int i = 0; i < ACC; i++) {
        acc[i] = coopmat<float, gl_ScopeSubgroup, TILE_M, TILE_N, gl_MatrixUseAccumulator>(float(i));
    }
    for (uint r = 0u; r < pc.reps; r++) {
        for (int i = 0; i < ACC; i++) {
            acc[i] = coopMatMulAdd(matA, matB, acc[i]);
        }
    }
    coopmat<float, gl_ScopeSubgroup, TILE_M, TILE_N, gl_MatrixUseAccumulator> sum = acc[0];
    for (int i = 1; i < ACC; i++) {
        sum += acc[i];
    }
    coopMatStore(sum, dst, gl_WorkGroupID.x * TILE_M * TILE_N, TILE_N, gl_CooperativeMatrixLayoutRowMajor);

#elif defined(MODE_WMMA_I8)
    coopmat<int8_t, gl_ScopeSubgroup, TILE_M, TILE_K, gl_MatrixUseA> matA;
    coopmat<int8_t, gl_ScopeSubgroup, TILE_K, TILE_N, gl_MatrixUseB> matB;
    coopMatLoad(matA, src, 0, TILE_K, gl_CooperativeMatrixLayoutRowMajor);
    coopMatLoad(matB, src, 0, TILE_N, gl_CooperativeMatrixLayoutRowMajor);

    coopmat<int32_t, gl_ScopeSubgroup, TILE_M, TILE_N, gl_MatrixUseAccumulator> acc[ACC];
    for (int i = 0; i < ACC; i++) {
        acc[i] = coopmat<int32_t, gl_ScopeSubgroup, TILE_M, TILE_N, gl_MatrixUseAccumulator>(i);
    }
    for (uint r = 0u; r < pc.reps; r++) {
        for (int i = 0; i < ACC; i++) {
            acc[i] = coopMatMulAdd(matA, matB, acc[i]);
        }
    }
    coopmat<int32_t, gl_ScopeSubgroup, TILE_M, TILE_N, gl_MatrixUseAccumulator> sum = acc[0];
    for (int i = 1; i < ACC; i++) {
        sum += acc[i];
    }
    coopMatStore(sum, dst, gl_WorkGroupID.x * TILE_M * TILE_N, TILE_N, gl_CooperativeMatrixLayoutRowMajor);

#elif defined(MODE_PKFMA)
    // Written as a*b + acc rather than fma() so it compiles without relying
    // on float16 fma() overloads; ACO fuses it into v_pk_fma_f16 either way.
    f16vec2 a = f16vec2(src[lid], src[lid + 64u]);
    f16vec2 b = f16vec2(src[lid + 128u], src[lid + 192u]);
    f16vec2 acc[ACC];
    for (int i = 0; i < ACC; i++) {
        acc[i] = a + f16vec2(float16_t(i));
    }
    for (uint r = 0u; r < pc.reps; r++) {
        for (int i = 0; i < ACC; i++) {
            acc[i] = a * b + acc[i];
        }
    }
    f16vec2 s = f16vec2(0.0hf);
    for (int i = 0; i < ACC; i++) {
        s += acc[i];
    }
    dst[gid] = float(s.x) + float(s.y);

#elif defined(MODE_DOT4)
    // The accumulating form (v_dot4_i32_i8 with its accumulator operand) is
    // what creates the loop-carried dependency; the non-accumulating
    // dotPacked4x8EXT would be loop-invariant and get hoisted.
    int a = int(src[lid]);
    int b = int(src[lid + 64u]);
    int acc[ACC];
    for (int i = 0; i < ACC; i++) {
        acc[i] = i;
    }
    for (uint r = 0u; r < pc.reps; r++) {
        for (int i = 0; i < ACC; i++) {
            acc[i] = dotPacked4x8AccSatEXT(a, b, acc[i]);
        }
    }
    int s = 0;
    for (int i = 0; i < ACC; i++) {
        s += acc[i];
    }
    dst[gid] = s;

#else // MODE_FMA
    float a = src[lid];
    float b = src[lid + 64u];
    float acc[ACC];
    for (int i = 0; i < ACC; i++) {
        acc[i] = a + float(i);
    }
    for (uint r = 0u; r < pc.reps; r++) {
        for (int i = 0; i < ACC; i++) {
            acc[i] = fma(a, b, acc[i]);
        }
    }
    float s = 0.0;
    for (int i = 0; i < ACC; i++) {
        s += acc[i];
    }
    dst[gid] = s;
#endif
}
=====PROBE
// Command probe dispatches a single SPIR-V compute shader once, so the RADV
// debug environment variables can be pointed at it: `RADV_DEBUG=asm` prints
// the generated RDNA disassembly and `RADV_DEBUG=shaderstats` the VGPR/SGPR,
// LDS and spill counts. That is IDEAS.md §6.1's "dump and read the ISA", and
// it is how the B-operand layout effect in shaders/gemm_wmma.comp was found:
// the instruction mix, not the timings, showed that a row-major
// cooperative-matrix B fragment is gathered by sixteen scalar 16-bit loads
// where a column-major one is two buffer_load_b128.
//
//	RADV_DEBUG=shaderstats go run ./cmd/probe shaders/gemm_wmma_reg64.spv
//	RADV_DEBUG=asm         go run ./cmd/probe shaders/gemm_wmma_reg64.spv
//
// An optional second argument pins the wave size the shader is compiled for
// (IDEAS.md §6.2), which is the only way to see what a variant costs at
// wave32 — the register file is per lane, so the VGPR count RADV prints is a
// different number at each size and it is the number that decides how far the
// hoisting ladder of §2.7 can go:
//
//	RADV_DEBUG=shaderstats go run ./cmd/probe shaders/gemm_wmma_reg64_w32.spv 32
//
// The shader is dispatched with one workgroup, zeroed push constants, and a
// single small buffer bound at every binding it declares, so it is only
// useful for compilation-time questions — nothing it prints depends on the
// shader computing anything meaningful. Kernels that need real buffers or a
// real grid belong in the bench suite, not here.
package main

import (
	"fmt"
	"log"
	"os"
	"strconv"

	"strix-halo-vulkan/vk"
)

const strixHaloDeviceID = 0x1586

// probeBindings is bound-above the binding count of any shader here; extra
// descriptors in the set are harmless, a missing one is not.
const probeBindings = 8

// probePushConstants is likewise bound-above the push-constant block of any
// shader here (the largest is the VAE's 88 bytes, vae_common.glsl). A layout
// range smaller than the block the shader declares is invalid, so err large.
const probePushConstants = 128

func main() {
	if len(os.Args) != 2 && len(os.Args) != 3 {
		log.Fatalf("usage: %s <shader.spv> [subgroup-size]", os.Args[0])
	}
	subgroupSize := 0
	if len(os.Args) == 3 {
		n, err := strconv.Atoi(os.Args[2])
		if err != nil {
			log.Fatalf("subgroup size %q: %v", os.Args[2], err)
		}
		subgroupSize = n
	}
	if err := run(os.Args[1], uint32(subgroupSize)); err != nil {
		log.Fatal(err)
	}
}

func run(path string, subgroupSize uint32) error {
	spirv, err := os.ReadFile(path)
	if err != nil {
		return err
	}

	instance, err := vk.NewInstance("strix-halo-probe")
	if err != nil {
		return err
	}
	defer instance.Destroy()

	devices, err := instance.PhysicalDevices()
	if err != nil {
		return err
	}
